function _transfer(address _from, address _to, uint _value) internal {
trequire (_to != 0x0);
trequire (balanceOf[_from] >= _value);
trequire (balanceOf[_to] + _value > balanceOf[_to]);
trequire(!frozenAccount[_from]);
trequire(!frozenAccount[_to]);
tbalanceOf[_from] -= _value;
tbalanceOf[_to] += _value;
tTransfer(_from, _to, _value);
tassert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function mintToken(address target, uint256 mintedAmount) onlyOwner public {
tbalanceOf[target] += mintedAmount;
ttotalSupply += mintedAmount;
tTransfer(0, this, mintedAmount);
tTransfer(this, target, mintedAmount);
}

function setPrices(uint256 newSellPrice, uint256 newBuyPrice) onlyOwner public {
tsellPrice = newSellPrice;
tbuyPrice = newBuyPrice;
}

function buy() payable public {
tuint amount = msg.value / buyPrice;
t_transfer(this, msg.sender, amount);
}
